original_card.content:
{% set printer = states('sensor.prusaxl') %}
{% set progress = states('sensor.prusaxl_status') %}
{% set finish = as_timestamp(states('sensor.prusaxl_utskriften_ar_fardig'), none) %}
<ha-icon icon="mdi:printer-3d-nozzle"></ha-icon> **Prusa XL · {{ 'Pausad' if printer == 'paused' else 'Skriver ut' }}**

{% if is_number(progress) %}**{{ progress | float | round(0) | int }} %** klart{% else %}Förlopp saknas{% endif %} · {% if printer == 'paused' %}Återstående tid uppdateras när utskriften fortsätter{% elif finish is not none and finish > as_timestamp(now()) %}{% set minutes = ((finish - as_timestamp(now())) / 60) | round(0, 'ceil') | int %}Cirka {% if minutes >= 60 %}{{ minutes // 60 }} h {% endif %}{{ minutes % 60 }} min kvar{% else %}Inväntar ny sluttidsprognos{% endif %}

style.ha-markdown$:
ha-icon {
  color: #FE6E31;
  --mdc-icon-size: 24px;
  display: inline-block;
  margin-right: 6px;
  vertical-align: middle;
  animation: {{ 'printer-soft-pulse 3s ease-in-out infinite' if is_state('sensor.prusaxl', 'printing') else 'none' }};
}
@keyframes printer-soft-pulse {
  0%, 100% { opacity: 1; filter: drop-shadow(0 0 3px rgba(254,110,49,0.45)); }
  50% { opacity: 0.5; filter: drop-shadow(0 0 0px rgba(254,110,49,0)); }
}
@media (prefers-reduced-motion: reduce) {
  ha-icon { animation: none; }
}

